module TopModule (
    input  [254:0] in,
    output [7:0]   out
);

    // Function to count the number of 1s in a binary vector
    function [7:0] popcount;
        input [254:0] data;
        integer i;
        reg [7:0] count;
        begin
            count = 8'b0;
            for (i = 0; i < 255; i = i + 1) begin
                if (data[i])
                    count = count + 1'b1;
            end
            popcount = count;
        end
    endfunction

    assign out = popcount(in);

endmodule

