    // Combinational population count using built-in $countones.
    // $countones counts the number of 1 bits in the concatenation of its arguments.
    // Here we count the bits in the 255-bit input vector.
    assign out = $countones(in);

endmodule

module TopModule (
    input  logic [254:0] in,
    output logic [7:0]   out
);

    // Internal signals for each 8-bit group popcount result
    logic [7:0] group_count;

    // Instantiate 32 popcount units for groups of 8 bits (32 * 8 = 256 bits)
    // The topmost bit (bit 254) is tied to 0; the circuit counts bits 254 down to 1,
    // effectively counting only the 255 input bits.
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin: popcount_group
            // Assign the 8-bit slice. For the last group (i=31), bit 254 is 0.
            // For all other groups, we take in[8*i +: 8].
            assign group_count[i] = (i == 31) 
                ? |in[8*i -: 7]  // Count ones in bits 254 down to 247 (7 bits) plus the implicit 0
                : |in[8*i +: 8]; // Count ones in the 8-bit slice
        end
    endgenerate

    // Sum the 32 group counts (each 0-8) into an 8-bit result.
    always_comb begin
        out = group_count[0] + group_count[1] + group_count[2] + group_count[3] +
              group_count[4] + group_count[5] + group_count[6] + group_count[7] +
              group_count[8] + group_count[9] + group_count[10] + group_count[11] +
              group_count[12] + group_count[13] + group_count[14] + group_count[15] +
              group_count[16] + group_count[17] + group_count[18] + group_count[19] +
              group_count[20] + group_count[21] + group_count[22] + group_count[23] +
              group_count[24] + group_count[25] + group_count[26] + group_count[27] +
              group_count[28] + group_count[29] + group_count[30] + group_count[31];
    end

endmodule

