module TopModule (
    input  logic clk,
    input  logic j,
    input  logic k,
    output logic Q
);

    // Internal storage for the flip-flop output
    logic Q_internal;

    // Synchronous reset is not specified, so Q_internal initializes to 0
    // by default in simulation, but synthesis tools may vary.
    // We explicitly initialize to 0 for synthesis compatibility.
    initial begin
        Q_internal = 1'b0;
    end

    always_ff @(posedge clk) begin
        case ({j, k})
            2'b00: Q_internal <= Q_internal;  // Hold state (Qold)
            2'b01: Q_internal <= 1'b0;          // Reset
            2'b10: Q_internal <= 1'b1;          // Set
            2'b11: Q_internal <= ~Q_internal;   // Toggle (~Qold)
            default: Q_internal <= 1'b0;        // Fallback (should not occur)
        endcase
    end

    // Assign the output port
    assign Q = Q_internal;

endmodule

module TopModule (
    input  clk,
    input  j,
    input  k,
    output Q
);

    // Internal signal to hold the previous state
    reg Q_reg;

    // Synchronous always block triggered on the positive clock edge
    always @(posedge clk) begin
        case ({j, k})
            2'b00: Q_reg <= Q_reg;       // Hold state (Qold)
            2'b01: Q_reg <= 1'b0;        // Reset
            2'b10: Q_reg <= 1'b1;        // Set
            2'b11: Q_reg <= ~Q_reg;      // Toggle
            default: Q_reg <= Q_reg;     // Default to hold (should not occur)
        endcase
    end

    // Continuous assignment to output the registered value
    assign Q = Q_reg;

endmodule

module TopModule (
    input  logic clk,
    input  logic j,
    input  logic k,
    output logic Q
);

    // Internal flip-flop state
    logic Q_reg;

    // Combinational logic for next state
    always_comb begin
        case ({j, k})
            2'b00: Q_reg = Q_reg;   // Hold state (Q_old)
            2'b01: Q_reg = 1'b0;    // Reset
            2'b10: Q_reg = 1'b1;    // Set
            2'b11: Q_reg = ~Q_reg;  // Toggle
            default: Q_reg = Q_reg;
        endcase
    end

    // Sequential logic (positive edge-triggered)
    always_ff @(posedge clk) begin
        Q_reg <= Q_reg;  // The actual assignment is handled by the combinational block above
    end

    // Assign output
    assign Q = Q_reg;

endmodule

module TopModule (
    input  logic clk,
    input  logic w,
    input  logic R,
    input  logic E,
    input  logic L,
    output logic Q
);

    always_ff @(posedge clk) begin
        if (L)
            Q <= R;
        else if (E)
            Q <= w;
    end

endmodule

module TopModule (
    input  logic clk,
    input  logic w,
    input  logic R,
    input  logic E,
    input  logic L,
    output logic Q
);

    // Internal register to hold the state
    logic q_reg;

    // Next-state logic
    always_comb begin
        // Default assignment: shift in 'w' if not loading
        // Priority: L (load) > E (shift) > Hold
        if (L)
            q_reg = R;          // Load R into Q
        else if (E)
            q_reg = w;          // Shift in w
        else
            q_reg = q_reg;      // Hold current value
    end

    // Sequential logic: positive edge triggered
    always_ff @(posedge clk) begin
        q_reg <= q_reg;       // Update register on clock edge
    end

    // Output assignment
    assign Q = q_reg;

endmodule

module TopModule (
    input  clk,
    input  w,
    input  R,
    input  E,
    input  L,
    output Q
);

    // Internal flip-flop to store the state
    reg Q_reg;

    // Synchronous logic triggered on the positive edge of clk
    always @(posedge clk) begin
        // Priority: Load (L) first, then Enable (E), then shift in w
        if (L) begin
            // Load the value from R
            Q_reg <= R;
        end else if (E) begin
            // Shift in the input from the previous stage
            Q_reg <= w;
        end else begin
            // Hold current value
            Q_reg <= Q_reg;
        end
    end

    // Continuous assignment for the output port
    assign Q = Q_reg;

endmodule

